import math
import re

from config import STOPWORDS, EXPANSIONS, BROAD_TERMS

_TOKEN_RE = re.compile(r"[a-z]+|[\u4e00-\u9fff]{2,}")
_CLAUSE_SPLIT_RE = re.compile(r"[?？;；!！]|(?:\band\b)|(?:\bor\b)|(?:以及)|(?:并且)|(?:和)|(?:、)|(?:,)|(?:，)")


def tokens(text):
    """Tokenize text into lowercase latin words and CJK runs."""
    return _TOKEN_RE.findall((text or "").lower())


def _normalize(terms):
    """Drop low-information question words."""
    return {t for t in terms if t not in STOPWORDS}


def _expand(terms):
    """Apply configured synonym expansions (both directions)."""
    expanded = set(terms)
    for key, synonyms in EXPANSIONS.items():
        key_terms = set(tokens(key))
        syn_terms = set()
        for syn in synonyms:
            syn_terms |= set(tokens(syn))
        if key_terms & terms:
            expanded |= syn_terms
        if syn_terms & terms:
            expanded |= key_terms
    return expanded


def _query_terms(query):
    raw = set(tokens(query))
    normalized = _normalize(raw)
    return _expand(normalized)


def _clauses(query):
    """Split a multi-part question into clauses and return per-clause terms."""
    parts = [p for p in _CLAUSE_SPLIT_RE.split(query or "") if p and p.strip()]
    result = []
    for part in parts:
        terms = _query_terms(part)
        if terms:
            result.append(terms)
    if not result:
        terms = _query_terms(query)
        if terms:
            result.append(terms)
    return result


def _downweight_broad(terms):
    """Return a weight map; broad parent terms are downweighted when a
    specific (non-broad) term is present."""
    weights = {t: 1.0 for t in terms}
    for parent, broads in BROAD_TERMS.items():
        parent_terms = set(tokens(parent))
        broad_terms = set()
        for b in broads:
            broad_terms |= set(tokens(b))
        specific_present = bool((terms - broad_terms) & (terms - parent_terms))
        if specific_present:
            for b in broad_terms:
                if b in weights:
                    weights[b] = 0.25
    return weights


def _chunk_terms(chunk):
    return set(tokens(chunk.get("text", "")))


def _score(chunk, weights, doc_freq, n_docs):
    """Combine term coverage with rarity (idf)."""
    cterms = _chunk_terms(chunk)
    if not cterms or not weights:
        return 0.0
    total_weight = sum(weights.values())
    if total_weight <= 0:
        return 0.0
    matched = 0.0
    for term, w in weights.items():
        if term in cterms:
            df = doc_freq.get(term, 0)
            idf = math.log((n_docs + 1) / (df + 1)) + 1.0
            matched += w * idf
    coverage = matched / total_weight
    # Length normalization: discourage tiny directory/title chunks from
    # dominating purely because they are short.
    length_norm = 1.0 + math.log(1.0 + len(cterms))
    return coverage * length_norm


def _page_key(chunk):
    return chunk.get("page")


def search_context(chunks, query, top_k=3, neighbor_window=1, max_context=8):
    chunks = list(chunks or [])
    if not chunks:
        return []

    n_docs = len(chunks)
    doc_freq = {}
    for c in chunks:
        for t in _chunk_terms(c):
            doc_freq[t] = doc_freq.get(t, 0) + 1

    clause_terms = _clauses(query)
    all_terms = set()
    for terms in clause_terms:
        all_terms |= terms
    weights = _downweight_broad(all_terms)

    scored = []
    for idx, c in enumerate(chunks):
        s = _score(c, weights, doc_freq, n_docs)
        scored.append((s, idx, c))
    scored.sort(key=lambda x: (-x[0], x[1]))

    selected = []
    selected_ids = set()

    def add(chunk, reason):
        cid = chunk.get("id")
        if cid in selected_ids:
            return False
        selected_ids.add(cid)
        selected.append({**chunk, "retrieval_reason": reason})
        return True

    # Reserve one positive semantic anchor per clause.
    for terms in clause_terms:
        cweights = _downweight_broad(terms)
        best = None
        best_score = 0.0
        for idx, c in enumerate(chunks):
            if c.get("id") in selected_ids:
                continue
            s = _score(c, cweights, doc_freq, n_docs)
            if s > best_score:
                best_score = s
                best = c
        if best is not None and len(selected) < max_context:
            add(best, "semantic")

    # Fill remaining semantic slots by overall score.
    for s, idx, c in scored:
        if len(selected) >= min(top_k, max_context):
            break
        if s <= 0:
            continue
        add(c, "semantic")

    # Add unique same-source neighboring pages.
    if neighbor_window and neighbor_window > 0:
        base = list(selected)
        for anchor in base:
            if len(selected) >= max_context:
                break
            source = anchor.get("source")
            page = _page_key(anchor)
            if page is None:
                continue
            for offset in range(1, neighbor_window + 1):
                for target in (page - offset, page + offset):
                    if len(selected) >= max_context:
                        break
                    for c in chunks:
                        if c.get("id") in selected_ids:
                            continue
                        if c.get("source") != source:
                            continue
                        if _page_key(c) != target:
                            continue
                        add(c, "neighbor")
                        break

    return selected[:max_context]

